#One My Annotations project. Each project is one SQL table and one track.
CREATE TABLE myVariantsProjects (
    id int unsigned not null AUTO_INCREMENT,	# Auto-increment primary key
    userName varchar(255) not null,	# Login of the user who owns the project
    dbTable varchar(255) not null,	# Fully qualified SQL table holding the annotations
    label varchar(255) not null,	# Project name as the user typed it; the track's short label
    createdAt timestamp not null default CURRENT_TIMESTAMP,	# Timestamp of creation
              #Indices
    PRIMARY KEY(id),
    UNIQUE KEY(dbTable),
    UNIQUE KEY userLabel(userName, label),
    KEY(userName)
) ENGINE=InnoDB;
